package cn.xingbao.controller;
import cn.xingbao.common.ApiResponse;import cn.xingbao.domain.LearningContent;import cn.xingbao.repo.LearningContentRepository;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1") public class LearningContentController {private final LearningContentRepository repo;public LearningContentController(LearningContentRepository repo){this.repo=repo;}@GetMapping("/learning-contents") public ApiResponse<List<LearningContent>> published(){return ApiResponse.ok(repo.findByPublishedTrueAndDeletedFalseOrderBySortOrderAscCreatedAtDesc());}@GetMapping("/admin/learning-contents") public ApiResponse<List<LearningContent>> all(){return ApiResponse.ok(repo.findByDeletedFalseOrderBySortOrderAscCreatedAtDesc());}@PostMapping("/admin/learning-contents") public ApiResponse<LearningContent> create(@RequestBody LearningContent input){return ApiResponse.ok(repo.save(normalize(input)));}@PutMapping("/admin/learning-contents/{id}") public ApiResponse<LearningContent> update(@PathVariable Long id,@RequestBody LearningContent input){LearningContent item=repo.findById(id).filter(x->!x.isDeleted()).orElseThrow(()->new IllegalArgumentException("内容不存在"));item.setCategory(input.getCategory());item.setIcon(input.getIcon());item.setTitle(input.getTitle());item.setReadingTime(input.getReadingTime());item.setIntro(input.getIntro());item.setSteps(input.getSteps());item.setTip(input.getTip());item.setSortOrder(input.getSortOrder());item.setPublished(input.isPublished());return ApiResponse.ok(repo.save(normalize(item)));}@PostMapping("/admin/learning-contents/{id}/published") public ApiResponse<LearningContent> publish(@PathVariable Long id,@RequestBody Map<String,Boolean> body){LearningContent item=repo.findById(id).filter(x->!x.isDeleted()).orElseThrow(()->new IllegalArgumentException("内容不存在"));item.setPublished(Boolean.TRUE.equals(body.get("published")));return ApiResponse.ok(repo.save(item));}@DeleteMapping("/admin/learning-contents/{id}") public ApiResponse<Void> delete(@PathVariable Long id){LearningContent item=repo.findById(id).filter(x->!x.isDeleted()).orElseThrow(()->new IllegalArgumentException("内容不存在"));item.setDeleted(true);repo.save(item);return ApiResponse.ok(null);}@SuppressWarnings("unchecked") private LearningContent normalize(LearningContent i){if(i.getTitle()==null||i.getTitle().isBlank())throw new IllegalArgumentException("请填写标题");if(i.getCategory()==null||i.getCategory().isBlank())i.setCategory("通用方法");if(i.getIcon()==null||i.getIcon().isBlank())i.setIcon("📖");if(i.getReadingTime()==null||i.getReadingTime().isBlank())i.setReadingTime("3 分钟");if(i.getSteps()==null)i.setSteps("");if(i.getSortOrder()==null)i.setSortOrder(100);return i;}}
